const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Body parsing middleware (if needed for POST/PUT requests)
// app.use(express.json());
// app.use(express.urlencoded({ extended: true }));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    // Don't expose internal details in production
    // uptime: process.uptime() 
  });
});

// Users endpoint
app.get('/users', (req, res) => {
  // In a real application, validate and sanitize any query parameters
  // Example: const { limit, offset } = req.query;
  // Validate limit and offset are numbers, within reasonable bounds, etc.

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource could not be found.'
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack); // Log error for internal monitoring

  // Don't leak stack trace in production
  const status = err.status || 500;
  const message = err.message || 'Internal Server Error';

  res.status(status).json({ 
    error: {
      message: process.env.NODE_ENV === 'production' ? 
               'An internal server error occurred' : 
               message,
      // Only include stack in non-production
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

